const quote = (step: QuoteStep): number => {
  const policyBasePremium = sum(step.items.map(basePremiumOf));
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return roundUpInMHPCOsFavour(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};
